import traceback
import json
from ute_common_abstract_core.exceptions import AbstractUeLibException


class MessageObserverTimeout(AbstractUeLibException):
    def __init__(self, message_type, owner, total_seen_messages, total_seen_messages_matching_protocol, last_seen_messages, validator=''):
        super(MessageObserverTimeout, self).__init__()
        self.message_type = message_type
        self.owner = owner
        self.total_seen_messages = total_seen_messages
        self.total_seen_messages_matching_protocol = total_seen_messages_matching_protocol
        self.last_seen_messages = last_seen_messages
        self.validator = validator
        self.owning_flow = None

    def __str__(self):
        cause = ""
        if self.total_seen_messages == 0:
            cause = "because no message has been caught before timeout"
        else:
            if self.total_seen_messages_matching_protocol == 0:
                cause = "because no message has been matching observed protocol"
            else:
                cause = "because none of {} caught messages has been accepted by '{}' filter before timeout"\
                    .format(self.total_seen_messages, self.validator)
        err = 'Observer for msg:{} owner:{} timeouted {}'.format(self.message_type, self.owner, cause)
        if self.owning_flow:
            err = "{} - {}".format(str(self.owning_flow), err)
        last_messages = self.parsed_last_messages()
        if last_messages:
            dumped_last_messages = self.dump_messages(last_messages)
            err += "\nlast %s messages seen:\n%s" % (len(last_messages), dumped_last_messages)
        return err

    def parsed_last_messages(self):
        """
        Parse some amount of last messages and returns.
        :return:
        """
        last_messages = []
        for unparsed_message in self.last_seen_messages:
            parsed_message = unparsed_message.parse()
            last_messages.append(parsed_message)
        return last_messages

    @staticmethod
    def dump_messages(parsed_messages):
        """
        Dumps to parsed asn values to json.
        :param parsed_messages:
        :return:
        """
        pretty_printed_msg = json.dumps(parsed_messages, indent=2)
        return pretty_printed_msg


class MessageObserverFailure(AbstractUeLibException):
    def __init__(self, observer_exception, message_type, owner):
        super(MessageObserverFailure, self).__init__()
        self.observer_exception = observer_exception
        self.message_type = message_type
        self.owner = owner
        self.stacktrace = traceback.format_exc()

    def __str__(self):
        err = 'Observer for msg:{} owner:{} failed because of:\n{}: {}'\
            .format(self.message_type, self.owner,
                    self.observer_exception.__class__.__name__,
                    self.observer_exception)
        return err + "\n" + self.stacktrace


class FailedMessageSubscription(AbstractUeLibException):
    def __init__(self, causing_exception, message_type, owner):
        super(FailedMessageSubscription, self).__init__()
        self.causing_exception = causing_exception
        self.message_type = message_type
        self.owner = owner
        self.stacktrace = traceback.format_exc()

    def __str__(self):
        err = "Message {} (owner:{}) subscription failed because of:\n{}: {}"\
            .format(self.message_type, self.owner,
                    self.causing_exception.__class__.__name__,
                    self.causing_exception)
        return err + "\n" + self.stacktrace


