class UserDefinedMessageVerifierDoesNotExist(AbstractUeLibException):
    def __init__(self, verifier, registered_verifiers):
        super(UserDefinedMessageVerifierDoesNotExist, self).__init__()
        self.verifier = verifier
        self.registered_verifiers = registered_verifiers

    def __str__(self):
        err = "Message verifier: {} supplied but NOT found in registered verifiers: {}," \
              " consider using @message_verifier decorator to mark the verifier or check verifiers spelling"\
            .format(self.verifier, self.registered_verifiers)
        return err


class VerifierContainsErrors(AbstractUeLibException):
    def __init__(self, verifier_sentence, error_value):
        super(VerifierContainsErrors, self).__init__()
        self.verifier_sentence = verifier_sentence
        self.error_value = error_value

    def __str__(self):
        err = "Message verifier: ({}) produces an error: ({}) instead of True/False value." \
              " Fix your code or contact library owners for further assistance"\
            .format(self.verifier_sentence, self.error_value)
        return err
